mapper.insert:
INSERT INTO SHOP_CART (
    CART_NUM
    , BOOK_NUM
    , CART_CNT
    , MEM_EMAIL
) VALUES (
    #{cartNum}
    , #{bookNum}
    , #{cartCnt}
    , #{memEmail}
)

mapper.select:
SELECT BOOK_NUM
FROM SHOP_CART
WHERE BOOK_NUM = #{bookNum}
AND MEM_EMAIL = #{memEmail};

mapper.update:
UPDATE SHOP_CART
SET CART_CNT = CART_CNT + #{cartCnt}
    , CART_DATE = SYSDATE()
WHERE BOOK_NUM = #{bookNum}
AND MEM_EMAIL = #{memEmail};

UPDATE SHOP_CART
SET CART_CNT = #{cartCnt},
    CART_NUM = #{cartNum}
WHERE CART_NUM = #{cartNum}
